import type { MapKey } from '../data/maps';
import type { Direction } from '../systems/movement';
import { MapScene } from './MapScene';

/**
 * A neighbouring province reached by road from Quảng Bình. Everything (walking,
 * doors, trees to chop, fishing, ghosts at night) comes from MapScene; the map
 * itself is generated by scripts/art/province_maps.py.
 */
export class ProvinceScene extends MapScene {
  constructor(key: MapKey) {
    super(key);
  }

  /** Arriving at the north edge you face south into the map, and vice versa. */
  protected override defaultFacing(spawn?: string): Direction {
    const at = this.findSpawn(spawn ?? 'default');
    if (at.x > this.worldSize.w - 8 * 16) return 'left'; // came in from the east edge
    return at.y < this.worldSize.h / 2 ? 'down' : 'up';
  }
}
